def transform(grid):
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]
    squares = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(original[rr][cc] == 2
                   for rr in (r, r + 1) for cc in (c, c + 1)):
                corners = [(r - 1, c - 1), (r - 1, c + 2),
                           (r + 2, c - 1), (r + 2, c + 2)]
                if all(0 <= rr < h and 0 <= cc < w
                       and original[rr][cc] != 0 for rr, cc in corners):
                    squares.append((r, c, corners))

    rays = []
    for r, c, corners in squares:
        tl, tr, bl, br = [original[rr][cc] for rr, cc in corners]
        colors = [bl, tl, br, tr]
        for (rr, cc), color in zip(corners, colors):
            out[rr][cc] = color
        rays.extend([
            (corners[0], -1, -1, colors[0]),
            (corners[1], -1,  1, colors[1]),
            (corners[2],  1, -1, colors[2]),
            (corners[3],  1,  1, colors[3]),
        ])

    def near_square(r, c):
        return any(
            abs(r - rr) <= 1 and abs(c - cc) <= 1
            for sr, sc, _ in squares
            for rr in (sr, sr + 1) for cc in (sc, sc + 1)
        )

    for (r, c), dr, dc, color in rays:
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if original[rr][cc] != 0:
                break
            # Stop before the ray reaches a cell beside a square.
            if near_square(rr, cc):
                break
            out[rr][cc] = color
            rr += dr
            cc += dc

    return out
